cd /tmp/akw-runs/final-codex-review; cat > /tmp/akw-scripts/dump.py <<'EOF'
import sys, openpyxl
for p in sys.argv[1:]:
    print("=====", p.split("/")[-1])
    wb = openpyxl.load_workbook(p, data_only=False)
    for ws in wb.worksheets:
        print("--- sheet", ws.title, ws.dimensions, ws.sheet_state)
        for row in ws.iter_rows():
            for c in row:
                if c.value is not None:
                    print(f"{c.coordinate}: {c.value!r}" + (f"  [comment: {c.comment.text}]" if c.comment else ""))
    print("defined names:", list(wb.defined_names.keys()) if hasattr(wb.defined_names,'keys') else wb.defined_names)
EOF
